:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent2: #0f3460;
  --text: #eaeaea;
  --cell: #0f3460;
  --cell-active: #e94560;
  --cell-playhead: #f5a623;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  width: 100%;
  max-width: 560px;
}

h1 {
  margin: 0 0 4px;
  font-size: 28px;
  letter-spacing: 1px;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 20px;
  font-size: 15px;
  opacity: 0.7;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.btn {
  font-size: 16px;
  font-family: inherit;
  padding: 10px 20px;
  border: 2px solid var(--accent2);
  border-radius: 8px;
  background: var(--accent2);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.btn:hover { background: #1a4a7a; border-color: #1a4a7a; }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn:active { transform: scale(0.96); }
.btn.primary { background: var(--accent); border-color: var(--accent); }
.btn.primary:hover { background: #ff5a75; border-color: #ff5a75; }
.btn.primary[aria-pressed="true"] { background: var(--cell-playhead); border-color: var(--cell-playhead); color: #1a1a2e; }

.bpm-label { font-size: 16px; opacity: 0.8; }

.bpm-input {
  width: 72px;
  font-size: 16px;
  font-family: inherit;
  padding: 8px;
  border: 2px solid var(--accent2);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  text-align: center;
}
.bpm-input:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
  margin-bottom: 16px;
}

.step {
  aspect-ratio: 1;
  min-width: 0;
  border: 2px solid var(--accent2);
  border-radius: 8px;
  background: var(--cell);
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s, transform 0.1s;
  padding: 0;
}

.step:hover { border-color: var(--accent); }
.step:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.step:active { transform: scale(0.92); }
.step.active { background: var(--cell-active); border-color: var(--cell-active); }
.step.playhead { border-color: var(--cell-playhead); box-shadow: 0 0 0 2px var(--cell-playhead); }
.step.active.playhead { background: var(--cell-playhead); border-color: var(--cell-playhead); }

.hint {
  margin: 0;
  font-size: 14px;
  opacity: 0.5;
  text-align: center;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  .grid { gap: 5px; }
  h1 { font-size: 24px; }
}

(function () {
  'use strict';

  var INSTRUMENTS = ['Kick', 'Snare', 'Hat', 'Clap'];
  var COLS = 8;
  var ROWS = 4;

  var grid = document.getElementById('grid');
  var playBtn = document.getElementById('playBtn');
  var clearBtn = document.getElementById('clearBtn');
  var bpmInput = document.getElementById('bpmInput');

  var state = [];
  var playing = false;
  var currentCol = -1;
  var timer = null;
  var audioCtx = null;

  // Build grid
  for (var r = 0; r < ROWS; r++) {
    state[r] = [];
    for (var c = 0; c < COLS; c++) {
      state[r][c] = false;
      var btn = document.createElement('button');
      btn.className = 'step';
      btn.type = 'button';
      btn.setAttribute('role', 'gridcell');
      btn.setAttribute('aria-label', INSTRUMENTS[r] + ' step ' + (c + 1));
      btn.setAttribute('aria-pressed', 'false');
      btn.dataset.row = r;
      btn.dataset.col = c;
      btn.addEventListener('click', onStepClick);
      grid.appendChild(btn);
    }
  }

  function onStepClick(e) {
    var btn = e.currentTarget;
    var r = parseInt(btn.dataset.row, 10);
    var c = parseInt(btn.dataset.col, 10);
    state[r][c] = !state[r][c];
    btn.classList.toggle('active', state[r][c]);
    btn.setAttribute('aria-pressed', String(state[r][c]));
  }

  function getBpm() {
    var v = parseInt(bpmInput.value, 10);
    if (isNaN(v) || v < 40) v = 40;
    if (v > 240) v = 240;
    bpmInput.value = v;
    return v;
  }

  function stepDuration() {
    return 60000 / getBpm() / 2; // eighth notes
  }

  function ensureAudio() {
    if (!audioCtx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (AC) audioCtx = new AC();
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
  }

  function playSound(row) {
    if (!audioCtx) return;
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    var freqs = [150, 220, 440, 330];
    osc.frequency.value = freqs[row];
    osc.type = row === 2 ? 'square' : 'sine';
    var now = audioCtx.currentTime;
    gain.gain.setValueAtTime(0.001, now);
    gain.gain.exponentialRampToValueAtTime(0.3, now + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(now);
    osc.stop(now + 0.13);
  }

  function highlightColumn(col) {
    var steps = grid.querySelectorAll('.step');
    for (var i = 0; i < steps.length; i++) {
      var s = steps[i];
      s.classList.toggle('playhead', parseInt(s.dataset.col, 10) === col);
    }
  }

  function tick() {
    currentCol = (currentCol + 1) % COLS;
    highlightColumn(currentCol);
    for (var r = 0; r < ROWS; r++) {
      if (state[r][currentCol]) playSound(r);
    }
  }

  function start() {
    ensureAudio();
    playing = true;
    playBtn.textContent = 'Stop';
    playBtn.setAttribute('aria-pressed', 'true');
    currentCol = -1;
    tick();
    timer = setInterval(tick, stepDuration());
  }

  function stop() {
    playing = false;
    playBtn.textContent = 'Play';
    playBtn.setAttribute('aria-pressed', 'false');
    clearInterval(timer);
    timer = null;
    currentCol = -1;
    highlightColumn(-1);
  }

  playBtn.addEventListener('click', function () {
    if (playing) stop(); else start();
  });

  clearBtn.addEventListener('click', function () {
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) {
        state[r][c] = false;
      }
    }
    var steps = grid.querySelectorAll('.step');
    for (var i = 0; i < steps.length; i++) {
      steps[i].classList.remove('active');
      steps[i].setAttribute('aria-pressed', 'false');
    }
  });

  bpmInput.addEventListener('change', function () {
    getBpm();
    if (playing) {
      clearInterval(timer);
      timer = setInterval(tick, stepDuration());
    }
  });
})();
